const ponds=[
 {id:'K01',name:'Kolam 01',dev:'ESP32-01',ph:9.21,temp:28.4,light:2240,turb:12.4,tds:1350,bio:1.42,harvest:'2–3 hari',pred:[1.45,1.49,1.53,1.58,1.62]},
 {id:'K02',name:'Kolam 02',dev:'ESP32-02',ph:7.62,temp:31.6,light:1200,turb:28.6,tds:1520,bio:1.08,harvest:'4–5 hari',pred:[1.12,1.15,1.19,1.23,1.27]},
 {id:'K03',name:'Kolam 03',dev:'ESP32-03',ph:9.05,temp:27.6,light:2860,turb:11.6,tds:1330,bio:1.36,harvest:'3 hari',pred:[1.40,1.44,1.48,1.52,1.56]},
 {id:'K04',name:'Kolam 04',dev:'ESP32-04',ph:8.74,temp:26.9,light:1980,turb:15.1,tds:1520,bio:1.11,harvest:'4 hari',pred:[1.15,1.19,1.23,1.27,1.31]}];
const R={ph:[8,11],temp:[20,30],light:[1000,3500],turb:[0,20],tds:[1000,1600]},CORE_PARAMETERS=['ph','temp','light'],WATER_QUALITY_PARAMETERS=['turb','tds'],f=n=>new Intl.NumberFormat('id-ID').format(n),main=document.querySelector('main');let p=ponds[1],view='dashboard';
// Single source of truth: all current values, charts, filters, and history are derived here.
const historyTemplates={K01:{ph:[9.02,9.08,9.14,9.10,9.18,9.16,9.21],temp:[27.5,27.9,28.1,27.8,28.3,28.0,28.4],light:[2100,2180,2260,2190,2300,2220,2240]},K02:{ph:[8.10,8.00,7.90,7.70,7.60,7.48,7.62],temp:[29.2,30.1,30.8,31.2,31.4,31.8,31.6],light:[1350,1300,1280,1250,1230,1210,1200]},K03:{ph:[8.92,9.01,9.08,9.00,9.12,9.03,9.05],temp:[27.1,27.4,27.8,27.5,27.7,27.4,27.6],light:[2700,2760,2810,2740,2890,2840,2860]},K04:{ph:[8.52,8.61,8.68,8.72,8.79,8.70,8.74],temp:[26.3,26.7,26.5,27.0,27.2,26.8,26.9],light:[1880,1930,1960,2010,1990,1950,1980]}};
const sensorData=ponds.flatMap(x=>historyTemplates[x.id].ph.map((ph,i)=>({id:`${x.id}-${i}`,kolamId:x.id,kolamNama:x.name,timestamp:`2026-08-${String(14+i).padStart(2,'0')}T10:30:00`,ph,suhu:historyTemplates[x.id].temp[i],cahaya:historyTemplates[x.id].light[i],turbidity:+(x.turb+(6-i)*.45).toFixed(1),tds:x.tds+(6-i)*4,biomassa:+(x.bio-(6-i)*.035).toFixed(2)})));
// Riwayat dapat datang dari API dalam urutan terbaru-ke-terlama. Selalu ambil
// pembacaan dengan timestamp paling baru agar seluruh tampilan memakai state aktual.
const latest=x=>sensorData.filter(d=>d.kolamId===x.id).reduce((newest, sample)=>!newest||new Date(sample.timestamp)>new Date(newest.timestamp)?sample:newest,null);
ponds.forEach(x=>{const d=latest(x);Object.assign(x,{ph:d.ph,temp:d.suhu,light:d.cahaya,turb:d.turbidity,tds:d.tds,bio:d.biomassa})});
const getParameterStatus=(key,value)=>R[key]?(value>=R[key][0]&&value<=R[key][1]?'OPTIMAL':'PERHATIAN'):'STABIL';
const getKolamStatus=x=>CORE_PARAMETERS.every(k=>getParameterStatus(k,x[k])==='OPTIMAL')?'OPTIMAL':'PERHATIAN';
let chartRange='7 Hari',chartParameter='Semua Parameter';
// Virtual hardware sends the same readings used by all views to the Laravel API.
const SENSOR_API_URL='http://127.0.0.1:8000/api/sensor-readings';
const SENSOR_INGEST_URL=SENSOR_API_URL;
let simulatorTimer=null;
let simulatorState={running:false,pondId:'K01',scenario:'normal',interval:5000,last:null,response:'Belum ada pengiriman',logs:[],restorePoint:null};
let farmerEditId=null;const farmerStorageKey='spirutwin-petani';let farmers=[];try{farmers=JSON.parse(localStorage.getItem(farmerStorageKey)||'[]')}catch(error){console.warn('Data petani lokal tidak dapat dibaca:',error.message)}
const usesWaterQualityCheck=x=>simulatorState.running&&simulatorState.pondId===x.id&&['kualitas_air_menurun','recovery'].includes(simulatorState.scenario);
const scenarioOptions={
 normal:{label:'Kondisi Normal',base:{ph:9.2,temp:28.2,light:2300,turb:13,tds:1350}},
 suhu_tinggi:{label:'Suhu Tinggi',base:{ph:9.4,temp:31.6,light:2300,turb:15,tds:1390}},
 suhu_rendah:{label:'Suhu Rendah',base:{ph:9.1,temp:18.5,light:2300,turb:15,tds:1390}},
 hujan:{label:'Hujan',base:{ph:8.7,temp:25.2,light:750,turb:22,tds:1310}},
 cahaya_rendah:{label:'Cahaya Rendah',base:{ph:9.0,temp:27.3,light:680,turb:15,tds:1350}},
 cahaya_tinggi:{label:'Cahaya Tinggi',base:{ph:9.0,temp:27.3,light:3650,turb:15,tds:1350}},
 ph_rendah:{label:'pH Rendah',base:{ph:7.35,temp:28.0,light:2200,turb:14,tds:1350}},
 ph_tinggi:{label:'pH Tinggi',base:{ph:11.55,temp:28.2,light:2300,turb:14,tds:1360}},
 kualitas_air_menurun:{label:'Kualitas Air Menurun',base:{ph:8.5,temp:29.1,light:1800,turb:34,tds:1680}},
 recovery:{label:'Pemulihan Bertahap',base:null}
};
const jitter=(base,span,precision=1)=>+(base+(Math.random()*2-1)*span).toFixed(precision);
const nowIso=()=>new Date().toISOString();
const addSimulatorHistory=sample=>sensorData.push(sample);
function syncPondsFromHistory(){ponds.forEach(pond=>{if(pond.id==='K02'&&simulatorState.last?.kolamId!=='K02')return;const sample=latest(pond);if(sample)Object.assign(pond,{ph:sample.ph,temp:sample.suhu,light:sample.cahaya,turb:sample.turbidity,tds:sample.tds,bio:sample.biomassa})})}
async function loadHistoryFromApi(){try{const response=await fetch(SENSOR_API_URL);if(!response.ok)throw new Error(`HTTP ${response.status}`);const records=await response.json();if(!Array.isArray(records))throw new Error('Format riwayat tidak valid');records.filter(record=>!sensorData.some(sample=>sample.id===record.id)).forEach(addSimulatorHistory);syncPondsFromHistory();render(view)}catch(error){console.warn('Riwayat database belum tersedia:',error.message)}}
const capturePondState=pond=>({id:pond.id,name:pond.name,ph:pond.ph,temp:pond.temp,light:pond.light,turb:pond.turb,tds:pond.tds,bio:pond.bio});
function restoreSimulatorState(){const saved=simulatorState.restorePoint;if(!saved)return false;const pond=ponds.find(x=>x.id===saved.id);if(!pond)return false;Object.assign(pond,{ph:saved.ph,temp:saved.temp,light:saved.light,turb:saved.turb,tds:saved.tds,bio:saved.bio});const restoredSample={id:`${pond.id}-stopped-${Date.now()}`,kolamId:pond.id,kolamNama:pond.name,timestamp:nowIso(),ph:saved.ph,suhu:saved.temp,cahaya:saved.light,turbidity:saved.turb,tds:saved.tds,biomassa:saved.bio};addSimulatorHistory(restoredSample);if(SENSOR_INGEST_URL)fetch(SENSOR_INGEST_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(restoredSample)}).catch(error=>console.warn('Status berhenti belum tersimpan:',error.message));simulatorState.restorePoint=null;simulatorState.response='STOPPED — kondisi sebelum simulator dipulihkan';return true}
function nextSimulatorSample(){const pond=ponds.find(x=>x.id===simulatorState.pondId),scenario=scenarioOptions[simulatorState.scenario];let values;
 if(simulatorState.scenario==='recovery'){values={ph:Math.min(9,jitter(pond.ph+(pond.ph<8?.45:pond.ph>11?-.45:0),.08,2)),temp:jitter(Math.max(25,Math.min(29,pond.temp)),.25),light:Math.max(1400,jitter(pond.light<1000?pond.light+350:pond.light,80,0)),turb:Math.max(12,jitter(pond.turb>18?pond.turb-2:pond.turb,.5)),tds:jitter(pond.tds>1600?pond.tds-40:pond.tds,15,0)}}
 else {const b=scenario.base;values={ph:jitter(b.ph,.22,2),temp:jitter(b.temp,.35),light:jitter(b.light,120,0),turb:jitter(b.turb,1.4),tds:jitter(b.tds,25,0)}}
 return {id:`${pond.id}-${Date.now()}`,kolamId:pond.id,kolamNama:pond.name,timestamp:nowIso(),ph:values.ph,suhu:values.temp,cahaya:values.light,turbidity:values.turb,tds:values.tds,biomassa:pond.bio};}
async function sendSimulatorSample(){const sample=nextSimulatorSample();addSimulatorHistory(sample);simulatorState.last=sample;syncPondsFromHistory();simulatorState.logs.unshift({sample,status:'LOCAL'});simulatorState.logs=simulatorState.logs.slice(0,8);simulatorState.response='LOCAL UPDATE — dashboard dan notifikasi diperbarui';render(view);try{if(!SENSOR_INGEST_URL)return;const response=await fetch(SENSOR_INGEST_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(sample)});if(!response.ok)throw new Error(`HTTP ${response.status}`);simulatorState.response='SUCCESS — tersimpan ke database';simulatorState.logs[0].status='SENT'}catch(error){simulatorState.response=`LOCAL UPDATE — database belum terhubung (${error.message})`;simulatorState.logs[0].status='LOCAL'}render(view)}
function simulator(){const s=simulatorState,last=s.last;return page('Sensor Simulator','Virtual hardware untuk mengirim pembacaan sensor ke sumber data SPIRUTWIN',`<div class="page-intro compact"><span class="eyebrow">VIRTUAL ESP32</span><h1>Sensor Simulator</h1><p>Interval demo dapat dipercepat. Pada hardware fisik, interval pembacaan dapat disesuaikan.</p></div><div class="simulator-layout"><section class="panel simulator-control"><h2>Konfigurasi Simulator</h2><div class="sim-fields"><label>Kolam<select id="simPond">${ponds.map(x=>`<option value="${x.id}" ${x.id===s.pondId?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Kondisi<select id="simScenario">${Object.entries(scenarioOptions).map(([key,x])=>`<option value="${key}" ${key===s.scenario?'selected':''}>${x.label}</option>`).join('')}</select></label><label>Interval<select id="simInterval">${[[5000,'5 detik'],[10000,'10 detik'],[30000,'30 detik'],[60000,'1 menit']].map(([v,l])=>`<option value="${v}" ${v===s.interval?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="sim-actions"><button class="primary-btn" id="startSimulator" ${s.running?'disabled':''}>▶ START SIMULATOR</button><button class="outline-btn" id="stopSimulator" ${!s.running?'disabled':''}>■ STOP SIMULATOR</button></div></section><section class="panel simulator-status"><h2>Simulator Status</h2><p><span class="${s.running?'ok-text':'amber-text'}">● ${s.running?'RUNNING':'STOPPED'}</span></p><p>Kolam <b>${ponds.find(x=>x.id===s.pondId).name}</b></p><p>Skenario <b>${scenarioOptions[s.scenario].label}</b></p><p>Last Sent <b>${last?formatWibTime(last.timestamp):'—'}</b></p><p>API Response <b>${s.response}</b></p></section></div><section class="panel simulator-data"><div class="panel-title"><div><h2>Data Terakhir</h2><p>Nilai mengikuti base value dan variasi kecil per skenario.</p></div></div>${last?`<div class="sim-reading-grid"><span>Suhu <b>${last.suhu}°C</b></span><span>pH <b>${last.ph}</b></span><span>Cahaya <b>${f(last.cahaya)} lux</b></span><span>Turbidity <b>${last.turbidity} NTU</b></span><span>TDS <b>${f(last.tds)} ppm</b></span></div>`:'<p class="muted-copy">Tekan START SIMULATOR untuk mulai mengirim data.</p>'}</section><section class="panel simulator-log"><div class="panel-title"><div><h2>Log Pengiriman</h2><p>Untuk debugging dan demo.</p></div></div>${s.logs.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Kolam</th><th>pH</th><th>Suhu</th><th>Status</th></tr></thead><tbody>${s.logs.map(x=>`<tr><td>${formatWibTime(x.sample.timestamp)}</td><td>${x.sample.kolamNama}</td><td>${x.sample.ph}</td><td>${x.sample.suhu}°C</td><td>${x.status}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted-copy">Belum ada pengiriman.</p>'}</section>`)}
// Isi koordinat lokasi budidaya yang sebenarnya sebelum aplikasi dipublikasikan.
// Sengaja tidak memakai lokasi browser maupun koordinat perkiraan.
const WEATHER_LOCATION={latitude:1.36,longitude:109.31,name:'Sambas, Kalimantan Barat'};
let lastWeather=null,weatherTimer=null;
function getWeatherInfo(code){if(code===0)return {icon:'☀',label:'Cerah'};if(code<=3)return {icon:'⛅',label:'Berawan'};if(code<=48)return {icon:'🌫',label:'Kabut'};if(code<=57)return {icon:'🌦',label:'Gerimis'};if(code<=67)return {icon:'🌧',label:'Hujan'};if(code<=77)return {icon:'❄',label:'Salju'};if(code<=82)return {icon:'🌧',label:'Hujan deras'};return {icon:'⛈',label:'Badai petir'}}
const weatherInfo=code=>{const info=getWeatherInfo(code);return [info.icon,info.label]};
const windDirection=deg=>['Utara','Timur Laut','Timur','Tenggara','Selatan','Barat Daya','Barat','Barat Laut'][Math.round(deg/45)%8];
const formatWibTime=value=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta',hour12:false}).format(new Date(value))+' WIB';
const wibTime=()=>formatWibTime(new Date());
const headerDate=()=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric'}).format(new Date());
const weatherMarkup=data=>{const c=data.current,icon=weatherInfo(c.weather_code),daily=data.daily;return `<div class="weather-current"><span class="weather-icon">${icon[0]}</span><div><strong>${Math.round(c.temperature_2m)}°C</strong><b>${icon[1]}</b><small>Terasa seperti ${Math.round(c.apparent_temperature)}°C</small></div><div class="weather-metrics"><span>Kelembapan <b>${c.relative_humidity_2m}%</b></span><span>Angin <b>${(c.wind_speed_10m/3.6).toFixed(1)} m/s</b></span><span>Arah <b>${windDirection(c.wind_direction_10m)}</b></span><span>Peluang hujan <b>${Math.round(daily.precipitation_probability_max[0])}%</b></span></div></div><div class="forecast-title">Prakiraan Cuaca</div><div class="forecast-days">${daily.time.slice(0,5).map((day,i)=>{let info=weatherInfo(daily.weather_code[i]),label=i===0?'Hari ini':i===1?'Besok':new Intl.DateTimeFormat('id-ID',{weekday:'short',timeZone:'Asia/Jakarta'}).format(new Date(`${day}T12:00:00`));return `<div><span>${label}</span><b>${info[0]}</b><strong>${Math.round(daily.temperature_2m_max[i])}°/${Math.round(daily.temperature_2m_min[i])}°</strong><small>${Math.round(daily.precipitation_probability_max[i])}%</small></div>`}).join('')}</div><p class="weather-updated">Terakhir diperbarui: ${wibTime()}</p>`};
async function fetchWeatherData(){const card=document.querySelector('.weather-info');if(!card)return;const content=card.querySelector('#weatherContent');if(!lastWeather)content.textContent='Memuat data cuaca...';try{console.log('Weather location:',WEATHER_LOCATION);const params=new URLSearchParams({latitude:WEATHER_LOCATION.latitude,longitude:WEATHER_LOCATION.longitude,current:'temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,rain,weather_code,cloud_cover,wind_speed_10m,wind_direction_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum',timezone:'Asia/Jakarta',forecast_days:'5'});const url=`https://api.open-meteo.com/v1/forecast?${params}`;console.log('Weather API URL:',url);const response=await fetch(url);if(!response.ok)throw new Error(`Weather API gagal: ${response.status}`);const data=await response.json();if(!data.current||!data.daily||data.daily.time.length<5)throw new Error('Respons Weather API tidak lengkap');console.log('Weather API response:',data);lastWeather=data;content.innerHTML=weatherMarkup(data)}catch(error){console.error('Weather API error:',error);content.innerHTML=lastWeather?weatherMarkup(lastWeather)+`<p class="weather-error">Data cuaca terbaru sementara tidak tersedia. Menampilkan data valid terakhir.</p>`:'<p class="weather-error">Data cuaca sementara tidak tersedia.</p>'}}
const problems=x=>[...CORE_PARAMETERS,...(usesWaterQualityCheck(x)?WATER_QUALITY_PARAMETERS:[])].filter(k=>x[k]<R[k][0]||x[k]>R[k][1]),state=x=>problems(x).length?'Perhatian':'Optimal',badge=x=>`<span class="badge ${state(x)==='Optimal'?'good':'warn'}">● ${state(x)}</span>`;
// Alert selalu dihitung dari pembacaan terakhir setiap kolam. Urutan terbaru di atas
// membuat pesan yang baru masuk langsung terlihat sebagai chat paling atas.
const alerts=()=>ponds.flatMap(x=>problems(x).map(k=>({x,k,timestamp:latest(x).timestamp}))).sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp));
const alertInfo=a=>{const value=a.x[a.k==='temp'?'temp':a.k],range=R[a.k],above=value>range[1],labels={ph:'pH',temp:'Suhu',light:'Cahaya',turb:'Kekeruhan',tds:'TDS'},units={ph:'',temp:'°C',light:' lux',turb:' NTU',tds:' ppm'},unit=units[a.k],formatted=['light','tds'].includes(a.k)?f(value):value,actions={ph:'Periksa kondisi media kultur dan lakukan penyesuaian pH secara bertahap. Pantau kembali hingga pH berada pada rentang ideal 8–11.',temp:'Periksa kondisi lingkungan kolam dan lakukan pengendalian suhu. Pantau kembali hingga suhu berada pada rentang ideal 20–30°C.',light:'Periksa kondisi pencahayaan kolam dan upayakan intensitas cahaya yang sesuai.',turb:'Periksa aerasi, endapan, dan indikasi kontaminasi. Lakukan penyaringan atau penggantian media secara bertahap, lalu pantau kekeruhan kembali.',tds:'Periksa konsentrasi nutrisi/media. Encerkan atau ganti sebagian media secara bertahap, lalu ukur TDS kembali.'};return {value:formatted+unit,ideal:`${['light','tds'].includes(a.k)?f(range[0]):range[0]}–${['light','tds'].includes(a.k)?f(range[1]):range[1]}${unit}`,message:`${labels[a.k]} ${above?'melebihi':'berada di bawah'} rentang ideal.`,action:actions[a.k]}};
function updateNotificationBadge(){const count=alerts().length,badge=document.querySelector('nav a[href="#notifikasi"] b');if(!badge)return;badge.textContent=count;badge.hidden=count===0;badge.setAttribute('aria-label',`${count} notifikasi aktif`)}
const page=(title,sub,body)=>`<header><button class="mobile-menu">☰</button><div class="page-title"><span>${title}</span><small>${sub}</small></div><div class="header-right"><span class="connected">● Terhubung</span><span class="date">▣ ${headerDate()}</span><span class="clock">◷ <time>${wibTime()}</time></span><div class="user"><div>AD</div><span>Administrator</span>⌄</div></div></header><section class="content">${body}</section>`;
const pick=()=>`<label class="select-label">Pilih Kolam <select id="pick">${ponds.map(x=>`<option value="${x.id}" ${x===p?'selected':''}>${x.name}</option>`)}</select></label>`;
const card=(n,v,u,ideal,bad,normalLabel='Optimal',normalText='● Dalam rentang ideal')=>`<article class="parameter ${bad?'needs-attention':''}"><div class="parameter-head"><span>${n}</span><b class="badge ${bad?'warn':'good'}">${bad?'⚠ Perhatian':normalLabel}</b></div><strong>${v} <small>${u}</small></strong><p>${ideal}</p><em class="${bad?'':'ok-text'}">${bad?'⚠ '+bad:normalText}</em></article>`;
const sensors=x=>{const waterQualityActive=usesWaterQualityCheck(x),turbidityProblem=waterQualityActive&&x.turb>R.turb[1]?'Di atas ideal':'',tdsProblem=waterQualityActive?(x.tds<R.tds[0]?'Di bawah ideal':x.tds>R.tds[1]?'Di atas ideal':''):'';return `<div class="parameter-grid sensor-grid">${card('pH Air',x.ph,'','Ideal: 8.00 – 11.00',x.ph<8?'Di bawah ideal':x.ph>11?'Di atas ideal':'')}${card('Suhu Air',x.temp,'°C','Ideal: 20 – 30 °C · optimum 25–30 °C',x.temp>30?'Di atas ideal':x.temp<20?'Di bawah ideal':'')}${card('Cahaya',f(x.light),'lux','Ideal: 1.000 – 3.500 lux',x.light<1000?'Di bawah ideal':x.light>3500?'Di atas ideal':'')}${card('Kekeruhan',x.turb,'NTU','Batas alert kualitas air: 0 – 20 NTU',turbidityProblem,'Stabil','● Parameter pemantauan')}${card('TDS',f(x.tds),'ppm','Batas alert kualitas air: 1.000 – 1.600 ppm',tdsProblem,'Stabil','● Parameter pemantauan')}</div>`};
const rows=()=>ponds.map(x=>`<tr><td><strong>${x.name}</strong><small>${x.dev}</small></td><td>${badge(x)}</td><td>${x.ph}</td><td>${x.temp} °C</td><td>${f(x.light)} lux</td><td><strong>${x.bio}</strong> kg/m³</td><td class="harvest">${x.harvest}</td><td><button class="detail-btn" data-detail="${x.id}">Detail</button></td></tr>`).join('');
function dashboard(){let good=ponds.filter(x=>state(x)==='Optimal').length,attention=ponds.length-good,a=alerts().length;return page('Dashboard Utama','Ringkasan kondisi budidaya Spirulina secara real-time',`<div class="welcome"><div><p>Selamat siang, Pembudidaya 👋</p><h1>Budidaya sehat, panen lebih tepat.</h1></div><button class="outline-btn" data-refresh>↻ Perbarui data</button></div><div class="stat-grid">${[['cyan','≋','Total Kolam','4','Kolam aktif'],['green','♧','Status Kolam',good,`${good} optimal · ${attention} perlu perhatian`],['purple','◌','Rata-rata Biomassa','1.24','kg/m³'],['orange','♧','Peringatan Aktif',a,'Butuh tindak lanjut'],['lime','▣','Panen Terdekat','2–3','hari · Kolam 01']].map(z=>`<article class="stat-card ${z[0]}"><div class="stat-icon">${z[1]}</div><p>${z[2]}</p><strong>${z[3]}</strong><small>${z[4]}</small></article>`).join('')}</div><section class="panel table-panel"><div class="panel-title"><div><h2>Ringkasan Semua Kolam</h2><p>Preview data sensor dari seluruh kolam</p></div><a href="#kolam" data-route="kolam">Lihat Semua Kolam →</a></div><div class="table-wrap"><table><thead><tr><th>Kolam</th><th>Status</th><th>pH</th><th>Suhu</th><th>Cahaya</th><th>Biomassa</th><th>Prediksi Panen</th><th></th></tr></thead><tbody>${rows()}</tbody></table></div></section>`)}
function kolam(){return page('Semua Kolam','4 kolam aktif · Data diperbarui setiap 5 menit',`<div class="page-intro"><span class="eyebrow">MONITORING KOLAM</span><h1>Kondisi setiap kolam budidaya</h1><p>Satu sumber data digunakan secara konsisten oleh semua halaman.</p></div><div class="pond-cards">${ponds.map(x=>`<article class="pond-card ${state(x)==='Perhatian'?'attention-card':''}"><div class="pond-card-top"><div><span class="eyebrow">${x.dev}</span><h2>${x.name}</h2></div>${badge(x)}</div><div class="pond-readings"><span>pH <b>${x.ph}</b></span><span>Suhu <b>${x.temp}°C</b></span><span>Cahaya <b>${f(x.light)} lux</b></span><span>Kekeruhan <b>${x.turb} NTU</b></span><span>TDS <b>${f(x.tds)} ppm</b></span></div><p class="${state(x)==='Optimal'?'ok-text':'reason'}">${state(x)==='Optimal'?'● Semua parameter utama berada dalam rentang ideal.':'⚠ pH, suhu, dan cahaya berada di luar rentang ideal.'}</p><div class="pond-card-foot"><span>Biomassa <strong>${x.bio} kg/m³</strong></span><span>Panen <strong>${x.harvest}</strong></span><button class="detail-btn" data-detail="${x.id}">Lihat Detail</button></div></article>`).join('')}</div>`)}
function detail(){let q=problems(p);return page(`Detail ${p.name}`,`${p.dev} · Data sensor terakhir 13:40 WIB`, `<div class="detail-hero"><div><span class="eyebrow">KONDISI KOLAM</span><h1>${p.name}</h1><p>${p.dev} &nbsp; ${badge(p)}</p></div><button class="outline-btn" data-route="kolam">← Kembali</button></div><section class="analysis-banner ${q.length?'attention-banner':''}"><b>${q.length?`⚠ Analisis kondisi: ${q.length} parameter di luar rentang ideal`:'✓ Analisis kondisi: semua parameter berada dalam rentang ideal'}</b><p>${q.length?'Sistem mendeteksi penyimpangan yang memerlukan pemantauan dan penyesuaian bertahap.':'Kolam mendukung pertumbuhan Spirulina.'}</p></section>${sensors(p)}<div class="detail-lower"><section class="panel"><h2>Analisis Sistem</h2><p>${q.length?`${q.length} parameter berada di luar kondisi ideal.`:'Tidak ada parameter utama di luar kondisi ideal.'}</p><ul>${q.map(k=>`<li>${k==='ph'?'pH berada di bawah rentang ideal 8–11.':k==='temp'?'Suhu melebihi batas ideal 20–30°C.':'Intensitas cahaya di bawah kebutuhan minimal 1.000 lux.'}</li>`).join('')||'<li>pH, suhu, dan cahaya dalam rentang ideal.</li>'}</ul></section><section class="panel recommendation"><h2>Rekomendasi</h2><p>Periksa media kultur dan sesuaikan parameter secara bertahap.</p><p>Pantau kembali pada pembacaan sensor berikutnya (5 menit).</p></section></div>`)}
function monitoring(){return page('Monitoring Real-time','Sensor IoT membaca kondisi kolam otomatis setiap 5 menit',`<div class="toolbar">${pick()}<span class="last-update">● Data terakhir: <b>13:40 WIB</b> · Pembaruan berikutnya otomatis</span></div><div class="page-intro compact"><span class="eyebrow">LIVE SENSOR</span><h1>${p.name} · ${badge(p)}</h1><p>${p.dev} mengirim data ke cloud melalui WiFi/MQTT.</p></div>${sensors(p)}<section class="panel data-flow"><h2>Alur data SPIRUTWIN</h2><p>Sensor → ESP32 → WiFi/MQTT → Cloud Server → evaluasi status → Dashboard & Telegram Bot</p></section>`)}
function analisis(){let charts=[['◒','pH',p.ph,'Ideal: 8.00 – 11.00','green','M0,84 C40,55 60,32 100,46 S160,86 200,70 S270,45 310,83 S380,70 420,38 S470,30 520,62'],['♨','Suhu Air (°C)',p.temp+'°C','Ideal: 20 – 30°C','red','M0,89 C40,48 60,25 105,38 S160,76 205,55 S280,22 320,28 S380,84 425,89 S480,50 520,63'],['☀','Cahaya (lux)',f(p.light)+' lux','Ideal: 1.000 – 3.500 lux','yellow','M0,48 C55,28 70,68 120,53 S190,35 240,65 S310,78 350,50 S430,22 520,43'],['◌','Kekeruhan (NTU)',p.turb+' NTU','Perlu pemantauan','blue','M0,66 C45,62 80,37 125,52 S190,78 240,60 S310,48 365,70 S440,42 520,58'],['≋','TDS (ppm)',f(p.tds)+' ppm','Monitoring media','purple','M0,57 C35,50 80,66 120,49 S190,34 250,57 S320,63 370,45 S440,32 520,53'],['◌','Biomassa (kg/m³)',p.bio+' kg/m³','Prediksi pertumbuhan','green','M0,89 C65,77 100,70 150,58 S220,49 270,40 S350,30 400,23 S460,14 520,8']];return page('Grafik & Analisis','Analisis perkembangan kondisi budidaya berdasarkan data sensor',`<div class="analysis-filter">${pick()}<label class="select-label">Rentang Waktu <select><option>24 Jam</option><option>7 Hari Terakhir</option><option>30 Hari Terakhir</option></select></label><label class="select-label">Parameter <select><option>Semua Parameter</option></select></label><button class="primary-btn">Terapkan</button></div><div class="chart-grid">${charts.map(c=>`<article class="panel compact-chart ${c[4]}"><div class="chart-card-title"><span>${c[0]}</span><div><h2>${c[1]}</h2><small>${c[3]}</small></div><strong>${c[2]}</strong></div><div class="chart-canvas"><i></i><svg viewBox="0 0 520 100" preserveAspectRatio="none"><path d="${c[5]}"/></svg><div class="chart-labels"><span>14 Agu</span><span>16 Agu</span><span>18 Agu</span><span>20 Agu</span></div></div></article>`).join('')}</div><section class="panel analysis-summary ${problems(p).length?'attention-banner':''}"><span class="eyebrow">ANALISIS KONDISI KOLAM</span><h2>${p.name} ${problems(p).length?`mengalami penyimpangan pada ${problems(p).length} parameter utama.`:'berada dalam kondisi ideal.'}</h2><p>${problems(p).length?'pH berada di bawah ideal, suhu berada di atas ideal, dan intensitas cahaya berada di bawah kebutuhan minimum.':'Seluruh parameter utama berada dalam rentang kondisi budidaya Spirulina yang aman.'}</p></section>`)}
function biomassa(){let target=p.pred[2];return page('Prediksi Biomassa','Model AI/ML memperkirakan pertumbuhan 3–7 hari ke depan',`<div class="toolbar">${pick()}</div><div class="biomass-summary-grid"><section class="panel biomass-ring-card"><h2>⌁ Prediksi Biomassa</h2><div class="biomass-ring"><div><strong>${p.bio}</strong><span>kg/m³</span></div></div><p>Prediksi 3 hari ke depan</p><b>${target} kg/m³</b><small>Rekomendasi Panen</small><strong class="date-panen">22 – 23 Agu 2026</strong><button class="outline-btn" data-route="analisis">Lihat Analisis Lengkap</button></section><section class="panel summary-alerts"><div class="panel-title"><h2>♧ Notifikasi & Peringatan</h2><a href="#notifikasi" data-route="notifikasi">Lihat Semua</a></div><div class="mini-notice">✓ ${p.name} · Prediksi panen dalam ${p.harvest} ke depan.</div><div class="mini-notice">✓ ${state(p)==='Optimal'?'Seluruh parameter berada dalam rentang ideal.':'Tiga parameter perlu dipantau sebelum panen.'}</div></section><section class="panel system-info"><h2>◉ Informasi Sistem</h2><p><span>Perangkat</span><b>${p.dev}</b></p><p><span>Status Koneksi</span><b class="ok-text">Terhubung</b></p><p><span>Mode</span><b>Otomatis</b></p><p><span>Interval Update</span><b>5 menit</b></p><p><span>Terakhir Diperbarui</span><b>Baru saja</b></p></section><section class="panel weather-info"><h2>☁ Kondisi Cuaca</h2><div class="weather-main"><span>☁</span><div><strong>28°C</strong><small>Berawan</small></div></div><p><span>Kelembaban</span><b>78%</b></p><p><span>Kecepatan Angin</span><b>2.3 m/s</b></p><p><span>Arah Angin</span><b>Timur</b></p></section></div>`)}
function twin(){const deviationCount=problems(p).length,visualState=deviationCount>1?'danger':deviationCount?'attention':'optimal',statusText=visualState==='optimal'?'OPTIMAL':visualState==='attention'?'PERHATIAN':'BAHAYA',statusCopy=visualState==='optimal'?'Semua parameter berada dalam rentang ideal.':'Terdapat parameter yang perlu ditangani.',parameterRows=[['pH',p.ph,'','8 – 11',p.ph>=8&&p.ph<=11?'OPTIMAL':'PERHATIAN'],['Suhu Air',p.temp,'°C','20 – 30',p.temp>=20&&p.temp<=30?'OPTIMAL':'PERHATIAN'],['Cahaya',f(p.light),'lux','1.000 – 3.500',p.light>=1000&&p.light<=3500?'OPTIMAL':'PERHATIAN'],['Kekeruhan',p.turb,'NTU','—','STABIL'],['TDS',f(p.tds),'ppm','—','STABIL']];return page('Digital Twin','Visualisasi kondisi kolam secara virtual',`<div class="twin-filter">${pick()}</div><div class="twin-dashboard"><section class="panel twin-visual"><div class="panel-title"><h2>▣ Digital Twin · ${p.name}</h2>${badge(p)}</div><div class="twin-pool twin-pool--${visualState}"><img src="assets/digital-twin-spirulina-pond.jpeg" alt="Visualisasi kolam budidaya Spirulina dengan aerator, pipa, sensor, dan panel sensor" /><span class="twin-pool-status" aria-hidden="true">${visualState==='optimal'?'●':'!'}</span><small>Simulasi visual kondisi kolam berdasarkan data sensor terkini</small></div></section><div class="twin-side"><section class="panel twin-status-summary twin-status-summary--${visualState}"><div><h2>Status Kolam</h2><b>${statusText}</b></div><p>${statusCopy}</p></section><section class="panel active-params twin-actual-params"><h2>Parameter Aktual</h2>${parameterRows.map(v=>`<p><span>${v[0]}</span><strong>${v[1]} <small>${v[2]}</small></strong><em>${v[3]}</em><b class="twin-status-${v[4].toLowerCase()}">${v[4]}</b></p>`).join('')}</section><section class="panel growth-summary"><h2>⌁ Ringkasan Pertumbuhan</h2><strong>${p.bio}</strong><small>kg/m³ saat ini</small><p><span>Laju Tumbuh</span><b class="ok-text">+0.86/hari</b></p><p><span>Estimasi Panen</span><b>${p.harvest}</b></p></section></div></div>`)}
function riwayat(){let logs=ponds.flatMap(x=>[0,1].map(i=>({x,i,ph:(x.ph+i*.09).toFixed(2),temp:(x.temp-i*.4).toFixed(1),light:x.light+i*30,turb:(x.turb-i*.7).toFixed(1),tds:x.tds-i*3})));return page('Riwayat Data','Log historis seluruh pembacaan sensor',`<div class="history-filters"><label>Kolam<select><option>Semua Kolam</option>${ponds.map(x=>`<option>${x.name}</option>`)}</select></label><label>Dari Tanggal<input type="date"></label><label>Sampai Tanggal<input type="date"></label><button class="primary-btn">Filter</button><button class="outline-btn">Reset</button></div><section class="panel table-panel history-table"><div class="panel-title"><div><h2>◷ Log Pembacaan Sensor</h2><p>Data tersimpan dari cloud server · interval 5 menit</p></div></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Kolam</th><th>pH</th><th>Suhu</th><th>Cahaya</th><th>Turbidity</th><th>TDS</th><th>Biomassa</th></tr></thead><tbody>${logs.map((v,i)=>`<tr><td>${i<4?'20':'19'} Agu 2026, 10:${30-i%2*5}</td><td><strong>${v.x.name}</strong></td><td>${v.ph}</td><td>${v.temp}°C</td><td>${f(v.light)} lux</td><td>${v.turb} NTU</td><td>${f(v.tds)} ppm</td><td>${v.x.bio} kg/m³</td></tr>`).join('')}</tbody></table></div></section>`)}
function notifikasi(){return page('Bot Telegram','Registrasi petani dan akses kondisi kolam melalui Telegram',`<div class="page-intro compact"><span class="eyebrow">INTEGRASI TELEGRAM</span><h1>Registrasi Petani melalui Bot</h1><p>Petani membuka <b>@Spirulinatwin_bot</b> dan menekan <b>/start</b>. Sistem mengenali mereka berdasarkan Telegram User ID, bukan username.</p></div><div class="settings-grid"><section class="panel"><h2>1. Petani terhubung</h2><p>Bot menyimpan Telegram User ID, chat ID, username (jika tersedia), nama, dan waktu terakhir berinteraksi.</p><p><span class="ok-text">● Tidak ada dashboard untuk petani</span></p></section><section class="panel"><h2>2. Admin menetapkan kolam</h2><p>Penugasan kolam dikelola dari <b>Data Petani</b>. Petani tidak memilih kolam melalui Telegram.</p><p>Perubahan assignment langsung menjadi sumber akses kondisi kolam.</p></section><section class="panel"><h2>3. Cek kondisi saat ini</h2><p>Tombol Telegram hanya menampilkan data sensor kolam yang ditugaskan kepada petani tersebut.</p><p><span class="amber-text">● Alert otomatis belum diaktifkan pada Step 2B</span></p></section></div>`)}
function pengaturan(){return page('Pengaturan','Sistem, akun, dan koneksi perangkat SPIRUTWIN',`<div class="settings-grid">${[['Sistem IoT','Interval sensor<br/>Setiap 5 menit','Protokol komunikasi<br/>WiFi / MQTT','Cloud Server<br/><span class="ok-text">● Terhubung</span>'],['Notifikasi','Tampilan Telegram Bot<br/><span class="amber-text">● Mode simulasi (belum terhubung)</span>','Status pesan<br/>Mengikuti kondisi sensor secara otomatis'],['Akun','Pembudidaya<br/>Politeknik Negeri Sambas','Peran<br/>Administrator Budidaya']].map(a=>`<section class="panel"><h2>${a[0]}</h2>${a.slice(1).map(s=>`<p>${s}</p>`).join('')}</section>`).join('')}</div>`)}
const nextFarmerCode=()=>`P${String(farmers.reduce((max,item)=>Math.max(max,Number(String(item.code||'').replace(/\D/g,''))||0),0)+1).padStart(3,'0')}`;
const telegramId=item=>item.telegramUserId||item.telegram_user_id||'—';
const telegramUsername=item=>item.telegramUsername||item.telegram_username||null;
const telegramSeenAt=item=>item.telegramLastSeenAt||item.telegram_last_seen_at||null;
const displayDate=value=>value?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Jakarta'}).format(new Date(value)):'Belum pernah /start';
const initials=name=>(name||'PT').trim().split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();
function petani(){const connected=farmers.filter(item=>telegramId(item)!=='—'),assigned=farmers.filter(item=>item.pond);return page('Data Petani','Kelola identitas Telegram dan penugasan kolam petani',`<div class="petani-page"><div class="petani-intro"><div><h1>Data Petani</h1><p>Kelola identitas Telegram dan penugasan kolam petani.</p></div><p class="petani-note">ⓘ Petani terdaftar otomatis saat menekan <b>/start</b> pada bot SPIRUTWIN.</p></div><div class="petani-stats"><article><span class="petani-stat-icon people">♧</span><div><small>TOTAL PETANI</small><strong>${farmers.length}</strong><p>Semua petani terdaftar</p></div></article><article><span class="petani-stat-icon telegram">➤</span><div><small>TERHUBUNG</small><strong>${connected.length}</strong><p>Akun aktif di Telegram</p></div></article><article><span class="petani-stat-icon pending">●</span><div><small>BELUM TERHUBUNG</small><strong>${farmers.length-connected.length}</strong><p>Belum pernah /start</p></div></article><article><span class="petani-stat-icon ponds">≋</span><div><small>KOLAM TERTUGAS</small><strong>${assigned.length} / ${farmers.length}</strong><p>Kolam yang diawasi</p></div></article></div><section class="panel petani-controls"><label>⌕ <input id="petaniSearch" placeholder="Cari nama, Telegram User ID, atau username..." /></label><select id="petaniStatus"><option value="all">Semua status</option><option value="connected">Terhubung</option><option value="pending">Belum terhubung</option><option value="assigned">Sudah ada kolam</option><option value="unassigned">Belum ada kolam</option></select><button class="outline-btn" id="refreshPetani">↻ Refresh</button></section><section class="panel petani-table"><div class="table-wrap"><table><thead><tr><th>PETANI</th><th>TELEGRAM</th><th>STATUS</th><th>KOLOM</th><th>TERAKHIR AKTIF</th><th>AKSI</th></tr></thead><tbody id="petaniTableBody">${farmers.length?farmers.map(item=>`<tr data-petani-row data-connected="${telegramId(item)!=='—'}" data-assigned="${Boolean(item.pond)}" data-search="${[item.name,telegramId(item),telegramUsername(item)||''].join(' ').toLowerCase()}"><td><span class="petani-avatar">${initials(item.name)}</span><strong>${item.name}</strong><small>Petani</small></td><td><strong>${telegramUsername(item)?'@'+telegramUsername(item):'—'}</strong><small>ID: ${telegramId(item)}</small></td><td><span class="badge ${telegramId(item)!=='—'?'good':'warn'}">● ${telegramId(item)!=='—'?'TERHUBUNG':'BELUM TERHUBUNG'}</span></td><td class="petani-pond ${item.pond?'':'unassigned'}">${ponds.find(pond=>pond.id===item.pond)?.name||'Belum ditentukan'}</td><td>${displayDate(telegramSeenAt(item))}</td><td><button class="detail-btn" data-farmer-edit="${item.id}">${item.pond?'Ubah Kolam':'Atur Kolam'}</button></td></tr>`).join(''):'<tr><td colspan="6">Belum ada data petani. Data akan muncul setelah petani menekan /start pada bot.</td></tr>'}</tbody></table></div><p class="petani-count" id="petaniCount">Menampilkan ${farmers.length} dari ${farmers.length} petani</p></section></div>`) }
const chartMeta={ph:['pH','green',[8,11]],suhu:['Suhu Air (°C)','red',[20,30]],cahaya:['Cahaya (lux)','yellow',[1000,3500]],turbidity:['Kekeruhan (NTU)','blue',null],tds:['TDS (ppm)','purple',null],biomassa:['Biomassa (kg/m³)','green',null]};
const chartPath=values=>{const w=520,h=100,min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.15,1),lo=min-pad,hi=max+pad;return values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1))*w},${h-((v-lo)/(hi-lo))*h}`).join(' ')};
const chartCard=(key,data)=>{let [label,color,ideal]=chartMeta[key],values=data.map(x=>x[key]),last=values.at(-1),ref=ideal?`Ideal: ${ideal[0]} – ${ideal[1]}`:'Tren berdasarkan data sensor';return `<article class="panel compact-chart ${color}"><div class="chart-card-title"><span>◒</span><div><h2>${label}</h2><small>${ref}</small></div><strong>${key==='cahaya'?f(last):last}${key==='suhu'?'°C':key==='cahaya'?' lux':key==='turbidity'?' NTU':key==='tds'?' ppm':key==='biomassa'?' kg/m³':''}</strong></div><div class="chart-canvas">${ideal?'<i></i>':''}<svg viewBox="0 0 520 100" preserveAspectRatio="none"><path d="${chartPath(values)}"/></svg><div class="chart-labels">${data.map(x=>`<span>${new Date(x.timestamp).getDate()} Agu</span>`).join('')}</div></div></article>`};
function analisis(){const mine=sensorData.filter(x=>x.kolamId===p.id),data=chartRange==='24 Jam'?mine.slice(-2):chartRange==='30 Hari'?mine:mine.slice(-7),keys=chartParameter==='Semua Parameter'?Object.keys(chartMeta):[chartParameter];return page('Grafik & Analisis','Analisis perkembangan kondisi budidaya berdasarkan data sensor',`<div class="analysis-filter">${pick()}<label class="select-label">Rentang Waktu <select id="range"><option ${chartRange==='24 Jam'?'selected':''}>24 Jam</option><option ${chartRange==='7 Hari'?'selected':''}>7 Hari</option><option ${chartRange==='30 Hari'?'selected':''}>30 Hari</option></select></label><label class="select-label">Parameter <select id="chartParam"><option>Semua Parameter</option>${Object.entries(chartMeta).map(([k,v])=>`<option value="${k}" ${chartParameter===k?'selected':''}>${v[0]}</option>`).join('')}</select></label><button class="primary-btn" id="applyChart">Terapkan</button></div><div class="chart-grid">${keys.map(k=>chartCard(k,data)).join('')}</div><section class="panel analysis-summary ${problems(p).length?'attention-banner':''}"><span class="eyebrow">ANALISIS KONDISI KOLAM</span><h2>${p.name} ${problems(p).length?`mengalami penyimpangan pada ${problems(p).length} parameter utama.`:'berada dalam kondisi ideal.'}</h2><p>Data terakhir ${new Date(data.at(-1).timestamp).toLocaleDateString('id-ID')} selalu digunakan sebagai nilai kartu dan status kolam.</p></section>`)}
const formatHistoryTimestamp=value=>new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));
function renderHistoryRows(data){return [...data].sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp)).map(x=>`<tr><td>${formatHistoryTimestamp(x.timestamp)}</td><td><strong>${x.kolamNama}</strong></td><td>${x.ph}</td><td>${x.suhu}°C</td><td>${f(x.cahaya)} lux</td><td>${x.turbidity} NTU</td><td>${f(x.tds)} ppm</td><td>${x.biomassa} kg/m³</td></tr>`).join('')}
function riwayat(){return page('Riwayat Data','Log historis seluruh pembacaan sensor',`<div class="history-filters"><label>Kolam<select id="historyPond"><option value="all">Semua Kolam</option>${ponds.map(x=>`<option value="${x.id}">${x.name}</option>`)}</select></label><label>Dari Tanggal<input id="historyStart" type="date"></label><label>Sampai Tanggal<input id="historyEnd" type="date"></label><button class="primary-btn" id="filterHistory">Filter</button><button class="outline-btn" id="resetHistory">Reset</button></div><section class="panel table-panel history-table"><div class="panel-title"><div><h2>◷ Log Pembacaan Sensor</h2><p id="historyCount">${sensorData.length} data tersimpan dari cloud server</p></div></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Kolam</th><th>pH</th><th>Suhu</th><th>Cahaya</th><th>Turbidity</th><th>TDS</th><th>Biomassa</th></tr></thead><tbody id="historyBody">${renderHistoryRows(sensorData)}</tbody></table></div></section>`)}
function applyHistoryFilter(){let pond=document.querySelector('#historyPond').value,start=document.querySelector('#historyStart').value,end=document.querySelector('#historyEnd').value;let startDate=start?new Date(`${start}T00:00:00`):null,endDate=end?new Date(`${end}T23:59:59`):null;let filtered=sensorData.filter(x=>{let sampleDate=new Date(x.timestamp);return (pond==='all'||x.kolamId===pond)&&(!startDate||sampleDate>=startDate)&&(!endDate||sampleDate<=endDate)});document.querySelector('#historyBody').innerHTML=renderHistoryRows(filtered)||'<tr><td colspan="8">Tidak ada data untuk filter ini.</td></tr>';document.querySelector('#historyCount').textContent=`${filtered.length} data ditampilkan`}
let modalPetaniId=null,modalSaving=false;
const pondName=id=>ponds.find(pond=>pond.id===id)?.name||'Belum ditentukan';
function closePetaniModal(){document.querySelector('.petani-modal-overlay')?.remove();modalPetaniId=null;modalSaving=false}
function openPetaniModal(id){const item=farmers.find(farmer=>farmer.id===id);if(!item)return;modalPetaniId=id;const overlay=document.createElement('div');overlay.className='petani-modal-overlay';overlay.innerHTML=`<section class="petani-modal" role="dialog" aria-modal="true" aria-labelledby="petaniModalTitle"><header><h2 id="petaniModalTitle">Ubah Penugasan Kolam</h2><button class="modal-close" type="button" aria-label="Tutup">×</button></header><div class="modal-body"><div class="modal-info"><small>PETANI</small><strong>${item.name}</strong><span>${item.code||'—'}</span></div><div class="modal-info"><small>TELEGRAM</small><strong>${telegramUsername(item)?'@'+telegramUsername(item):'Tidak tersedia'}</strong></div><div class="modal-info"><small>KOLAM SAAT INI</small><strong>${pondName(item.pond)}</strong></div><label class="modal-select-label">Pindahkan ke<select id="modalPondSelect"><option value="">Belum ditentukan</option>${ponds.map(pond=>`<option value="${pond.id}" ${pond.id===item.pond?'selected':''}>${pond.name}</option>`).join('')}</select></label></div><footer><button class="outline-btn modal-cancel" type="button">Batal</button><button class="primary-btn modal-save" type="button">Simpan Perubahan</button></footer></section>`;overlay.addEventListener('click',event=>{if(event.target===overlay)closePetaniModal()});document.body.appendChild(overlay);overlay.querySelector('.modal-close').focus()}
function savePetaniAssignment(){if(modalSaving||!modalPetaniId)return;const item=farmers.find(farmer=>farmer.id===modalPetaniId),select=document.querySelector('#modalPondSelect'),nextPond=select?.value;if(!item||nextPond===item.pond){closePetaniModal();return}const currentOwner=nextPond&&farmers.find(farmer=>farmer.id!==item.id&&farmer.pond===nextPond);if(currentOwner){openPetaniConfirmation(item,currentOwner,nextPond);return}commitPetaniAssignment(item,nextPond)}
function openPetaniConfirmation(item,currentOwner,nextPond){const modal=document.querySelector('.petani-modal');if(!modal)return;modal.innerHTML=`<header><h2>Konfirmasi Pemindahan</h2><button class="modal-close" type="button" aria-label="Tutup">×</button></header><div class="modal-body modal-confirm"><p><b>${pondName(nextPond)}</b> saat ini ditugaskan kepada <b>${currentOwner.name}</b>.</p><p>Apakah Anda yakin ingin memindahkan penugasan kolam ini ke <b>${item.name}</b>?</p></div><footer><button class="outline-btn modal-back" type="button">Batal</button><button class="primary-btn modal-confirm-save" type="button">Ya, Pindahkan</button></footer>`;modal.querySelector('.modal-close').onclick=closePetaniModal;modal.querySelector('.modal-back').onclick=()=>{modal.closest('.petani-modal-overlay')?.remove();openPetaniModal(item.id)};modal.querySelector('.modal-confirm-save').onclick=()=>commitPetaniAssignment(item,nextPond,currentOwner)}
function commitPetaniAssignment(item,nextPond,currentOwner=null){if(modalSaving)return;modalSaving=true;const button=document.querySelector('.modal-save,.modal-confirm-save');if(button){button.disabled=true;button.textContent='Menyimpan...'}setTimeout(()=>{const previous=item.pond,scrollPosition=window.scrollY;farmers=farmers.map(farmer=>farmer.id===item.id?{...farmer,pond:nextPond}:currentOwner&&farmer.id===currentOwner.id?{...farmer,pond:''}:farmer);localStorage.setItem(farmerStorageKey,JSON.stringify(farmers));closePetaniModal();toast(`✓ Penugasan berhasil diperbarui · ${item.name}: ${pondName(previous)} → ${pondName(nextPond)}`);render('petani');window.scrollTo({top:scrollPosition})},350)}
document.addEventListener('click',event=>{const edit=event.target.closest('[data-farmer-edit]');if(edit){event.preventDefault();openPetaniModal(edit.dataset.farmerEdit)}if(event.target.closest('.modal-close,.modal-cancel'))closePetaniModal();if(event.target.closest('.modal-save'))savePetaniAssignment()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('.petani-modal-overlay'))closePetaniModal()});
function filterPetaniRows(){const query=(document.querySelector('#petaniSearch')?.value||'').trim().toLowerCase(),status=document.querySelector('#petaniStatus')?.value||'all',rows=[...document.querySelectorAll('[data-petani-row]')];let shown=0;rows.forEach(row=>{const matchesQuery=!query||row.dataset.search.includes(query),matchesStatus=status==='all'||(status==='connected'&&row.dataset.connected==='true')||(status==='pending'&&row.dataset.connected==='false')||(status==='assigned'&&row.dataset.assigned==='true')||(status==='unassigned'&&row.dataset.assigned==='false'),visible=matchesQuery&&matchesStatus;row.hidden=!visible;if(visible)shown++});const count=document.querySelector('#petaniCount');if(count)count.textContent=`Menampilkan ${shown} dari ${rows.length} petani`}
document.addEventListener('input',event=>{if(event.target.id==='petaniSearch')filterPetaniRows()});
document.addEventListener('change',event=>{if(event.target.id==='petaniStatus')filterPetaniRows()});
document.addEventListener('click',event=>{if(event.target.id==='refreshPetani'){render('petani');toast('Data petani diperbarui.')}});
const views={dashboard,kolam,detail,monitoring,analisis,biomassa,twin,simulator,riwayat,notifikasi,petani,pengaturan};
function setupWeather(){const card=document.querySelector('.weather-info');if(!card){if(weatherTimer)clearInterval(weatherTimer);weatherTimer=null;return}card.innerHTML=`<div class="panel-title"><div><h2>Kondisi Cuaca Saat Ini</h2><p>${WEATHER_LOCATION.name}</p></div><button class="detail-btn" id="refreshWeather">↻ Perbarui</button></div><div id="weatherContent" class="weather-loading">Memuat data cuaca...</div>`;document.querySelector('#refreshWeather').onclick=fetchWeatherData;fetchWeatherData();if(weatherTimer)clearInterval(weatherTimer);weatherTimer=setInterval(fetchWeatherData,10*60*1000)}
function syncTwinParameters(){if(view!=='twin')return;const keys=['ph','temp','light','turb','tds'],ideals=['8 – 11','20 – 30','1.000 – 3.500','0 – 20','1.000 – 1.600'];document.querySelectorAll('.twin-actual-params p').forEach((row,index)=>{const key=keys[index],isSupplementary=WATER_QUALITY_PARAMETERS.includes(key),status=isSupplementary&&!usesWaterQualityCheck(p)?'STABIL':getParameterStatus(key,p[key]),ideal=row.querySelector('em'),badge=row.querySelector('b');ideal.textContent=ideals[index];badge.textContent=status;badge.className=`twin-status-${status.toLowerCase()}`})}
function render(v='dashboard'){view=v;main.innerHTML=views[v]();syncTwinParameters();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+v));updateNotificationBadge();bind();setupWeather()}
function bind(){document.querySelector('.mobile-menu')?.addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));document.querySelectorAll('[data-route]').forEach(e=>e.onclick=()=>render(e.dataset.route));document.querySelectorAll('[data-detail]').forEach(e=>e.onclick=()=>{p=ponds.find(x=>x.id===e.dataset.detail);render('detail')});document.querySelector('#pick')?.addEventListener('change',e=>{p=ponds.find(x=>x.id===e.target.value);render(view)});document.querySelector('[data-refresh]')?.addEventListener('click',()=>toast('Data sensor berhasil diperbarui · 13:40 WIB'));document.querySelector('#applyChart')?.addEventListener('click',()=>{chartRange=document.querySelector('#range').value;chartParameter=document.querySelector('#chartParam').value;render('analisis')});document.querySelector('#filterHistory')?.addEventListener('click',applyHistoryFilter);document.querySelector('#resetHistory')?.addEventListener('click',()=>{document.querySelector('#historyPond').value='all';document.querySelector('#historyStart').value='';document.querySelector('#historyEnd').value='';applyHistoryFilter()});document.querySelector('#startSimulator')?.addEventListener('click',()=>{simulatorState.pondId=document.querySelector('#simPond').value;simulatorState.scenario=document.querySelector('#simScenario').value;simulatorState.interval=+document.querySelector('#simInterval').value;simulatorState.restorePoint=capturePondState(ponds.find(x=>x.id===simulatorState.pondId));simulatorState.running=true;sendSimulatorSample();simulatorTimer=setInterval(sendSimulatorSample,simulatorState.interval)});document.querySelector('#stopSimulator')?.addEventListener('click',()=>{simulatorState.running=false;clearInterval(simulatorTimer);simulatorTimer=null;const restored=restoreSimulatorState();render('simulator');toast(restored?'Simulator dihentikan. Kondisi default kolam dipulihkan.':'Simulator dihentikan. Tidak ada data baru yang dikirim.')});document.querySelector('#run')?.addEventListener('click',()=>{let ph=+document.querySelector('#simPh').value,t=+document.querySelector('#simT').value,l=+document.querySelector('#simL').value,ok=ph>=8&&ph<=11&&t>=20&&t<=30&&l>=1000&&l<=3500;document.querySelector('#result').innerHTML=ok?'<span>Hasil simulasi</span><strong class="ok-text">PERHATIAN → OPTIMAL</strong><p>Prediksi biomassa: 1.08 → 1.34 kg/m³</p>':'<span>Hasil simulasi</span><strong class="amber-text">Status masih memerlukan perhatian</strong><p>Sesuaikan nilai hingga berada dalam rentang ideal.</p>'})}
document.addEventListener('change',e=>{if(e.target.id==='simPond')simulatorState.pondId=e.target.value;if(e.target.id==='simScenario')simulatorState.scenario=e.target.value;if(e.target.id==='simInterval'){simulatorState.interval=+e.target.value;if(simulatorState.running){clearInterval(simulatorTimer);simulatorTimer=setInterval(sendSimulatorSample,simulatorState.interval)}}});document.querySelectorAll('nav a').forEach(a=>a.onclick=e=>{if(!a.hash)return;e.preventDefault();render(a.hash.slice(1))});function toast(m){let t=document.querySelector('.toast')||Object.assign(document.body.appendChild(document.createElement('div')),{className:'toast'});t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}setInterval(()=>{let t=document.querySelector('time');if(t)t.textContent=new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Jakarta'}).format(new Date())+' WIB'},1000);render();loadHistoryFromApi();
